import { useState } from 'react';
import {
  JxCard,
  JxField,
  JxInput,
  JxHelperText,
  JxSelect,
  JxOption,
  JxSwitch,
  JxButton,
  JxAlert,
  JxStack,
} from '@jinx-ui/react';

const ROLES = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [touched, setTouched] = useState(false);
  const [success, setSuccess] = useState(false);

  const isEmailValid = EMAIL_RE.test(email);
  const showError = touched && !isEmailValid;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setTouched(true);
    if (!isEmailValid) return;

    setSuccess(true);
  };

  return (
    <JxStack direction="column" gap="var(--jx-space-4)" style={{ maxWidth: 420 }}>
      {success && (
        <JxAlert variant="success" onClose={() => setSuccess(false)}>
          Приглашение отправлено на {email}
        </JxAlert>
      )}

      <JxCard>
        <form onSubmit={handleSubmit}>
          <JxStack direction="column" gap="var(--jx-space-4)">
            <JxField invalid={showError}>
              <JxField.Label>Email</JxField.Label>
              <JxInput
                type="email"
                placeholder="name@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                onBlur={() => setTouched(true)}
                invalid={showError}
              />
              <JxHelperText variant={showError ? 'error' : 'default'}>
                {showError
                  ? 'Введите корректный email-адрес'
                  : 'Приглашение придёт на указанную почту'}
              </JxHelperText>
            </JxField>

            <JxField>
              <JxField.Label>Роль</JxField.Label>
              <JxSelect value={role} onChange={(value) => setRole(value as string)}>
                {ROLES.map((r) => (
                  <JxOption key={r.value} value={r.value}>
                    {r.label}
                  </JxOption>
                ))}
              </JxSelect>
            </JxField>

            <JxSwitch checked={notify} onChange={(e) => setNotify(e.target.checked)}>
              Отправить уведомление
            </JxSwitch>

            <JxButton type="submit" disabled={!isEmailValid}>
              Отправить приглашение
            </JxButton>
          </JxStack>
        </form>
      </JxCard>
    </JxStack>
  );
}

